messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html>
<head>
    <meta charset="utf-8">
    <title>3D Humanoid Cycle</title>
    <style>
        body { margin:0; overflow:hidden; }
        canvas { position:absolute; top:0; left:0; width:100vw; height:100vh; }
    </style>
</head>
<body>
    <canvas id="canvas"></canvas>
    <script type="module">
        import * as THREE from './three.module.js';

        const canvas = document.getElementById('canvas');
        const renderer = new THREE.WebGLRenderer({ canvas, antialias: true });
        const scene = new THREE.Scene();
        const camera = new THREE.PerspectiveCamera(45, canvas.clientWidth / canvas.clientHeight, 0.1, 1000);
        camera.position.set(10, 2, 0);
        camera.lookAt(scene.position);
        const light = new THREE.DirectionalLight(0xffffff, 1);
        light.position.set(5,5,5);
        scene.add(light);
        const ambient = new THREE.AmbientLight(0x404040);
        scene.add(ambient);

        const geometry = new THREE.IcosahedronGeometry(1,4);
        const material = new THREE.MeshStandardMaterial({ color:0x00ff00 });
        const humanoid = new THREE.Mesh(geometry, material);
        scene.add(humanoid);

        const limbLength = 1.5;
        const limbWidth  = 0.15;
        const legCount   = 2;
        const armCount   = 2;

        const legGeom = new THREE.CylinderGeometry(limbWidth, limbWidth, limbLength, 6, 6);
        const armGeom = new THREE.CylinderGeometry(limbWidth, limbWidth, limbLength, 6, 6);

        const legs = [];
        for (let i=0; i<legCount; i++) {
            const leg = new THREE.Mesh(limbGeom.clone(), material.clone());
            leg.position.set(0,0,0);
            leg.rotation.x = Math.PI/2;
            scene.add(leg);
            legs.push(leg);
        }
        const arms = [];
        for (let i=0; i<armCount; i++) {
            const arm = new THREE.Mesh(armGeom.clone(), material.clone());
            arm.position.set(0,0,0);
            arm.rotation.x = Math.PI/2;
            scene.add(arm);
            arms.push(arm);
        }

        const legPos = legs.map(l => l.position.clone());
        const armPos = arms.map(a => a.position.clone());

        const clock = new THREE.Clock();

        const cycle = () => {
            const t = clock.getElapsedTime();

            const stand = Math.floor(t) % 10 < 2; // 0-2 stand, 2-5 walk, 5-8 run, 8-10 stand
            const standTime = Math.floor(t) % 10;
            const walkTime  = Math.floor(t) % 10;
            const runTime   = Math.floor(t) % 10;

            const standDur = 2; // seconds
            const walkDur  = 3; // seconds
            const runDur   = 3; // seconds

            const current = Math.floor(t) % 10;

            // ---- STAND ----
            if (current < 2) {
                // stand still
                humanoid.rotation.set(0,0,0);
                legs.forEach(l => l.rotation.set(0,0,0));
                arms.forEach(a => a.rotation.set(0,0,0));
            }
            // ---- WALK ----
            else if (current < 5) {
                const walkProgress = (t % 5); // 0-3
                const legSpeed = 0.5; // rad per sec
                const armSpeed = 0.8;
                const legSwing = Math.sin(walkProgress * Math.PI * 2 / 5);
                const armSwing = Math.sin(walkProgress * Math.PI * 2 / 5);
                const legAngle = Math.PI/2 + legSwing;
                const armAngle = Math.PI/2 + armSwing;

                // legs: alternate
                legs.forEach((l, idx) => {
                    const phase = idx % 2;
                    const offset = phase * Math.PI/2;
                    const targetAngle = offset + legSwing;
                    const curAngle = Math.PI/2 + Math.sin(walkProgress * Math.PI * 2 / 5 + idx*Math.PI/2);
                    const interp = Math.sin(walkProgress * Math.PI * 2 / 5 + idx*Math.PI/2);
                    const target = Math.PI/2 + interp;
                    const cur = Math.PI/2 + Math.sin(walkProgress * Math.PI * 2 / 5 + idx*Math.PI/2);
                    const delta = target - cur;
                    const speed = 1.5; // rad per sec
                    const add = speed * (clock.getElapsedTime() - (t - (walkDur*Math.floor(t/5))));
                    const newAngle = cur + delta * (1 - (t - Math.floor(t)) * 5);
                    l.rotation.set(0,0,newAngle);
                });

                // arms: alternate
                arms.forEach((a, idx) => {
                    const phase = idx % 2;
                    const targetAngle = Math.PI/2 + Math.sin(walkProgress * Math.PI * 2 / 5 + idx*Math.PI/2);
                    const curAngle = Math.PI/2 + Math.sin(walkProgress * Math.PI * 2 / 5 + idx*Math.PI/2);
                    const delta = targetAngle - curAngle;
                    const speed = 1.2;
                    const add = speed * (clock.getElapsedTime() - (t - Math.floor(t/5)*5));
                    const newAngle = curAngle + delta * (1 - (t - Math.floor(t)) * 5);
                    a.rotation.set(0,0,newAngle);
                });
            }
            // ---- RUN ----
            else if (current < 8) {
                const runProgress = t % 5; // 0-3
                const legSpeed = 1.2;
                const armSpeed = 1.0;
                const legSwing = Math.sin(runProgress * Math.PI * 2 / 5);
                const armSwing = Math.sin(runProgress * Math.PI * 2 / 5);
                const legAngle = Math.PI/2 + legSwing;
                const armAngle = Math.PI/2 + armSwing;

                legs.forEach((l, idx) => {
                    const phase = idx % 2;
                    const targetAngle = Math.PI/2 + legSwing + (phase*Math.PI/2);
                    const curAngle = Math.PI/2 + Math.sin(runProgress * Math.PI * 2 / 5 + idx*Math.PI/2);
                    const delta = targetAngle - curAngle;
                    const speed = 2.0;
                    const add = speed * (clock.getElapsedTime() - (t - Math.floor(t/5)*5));
                    const newAngle = curAngle + delta * (1 - (t - Math.floor(t)) * 5);
                    l.rotation.set(0,0,newAngle);
                });

                arms.forEach((a, idx) => {
                    const phase = idx % 2;
                    const targetAngle = Math.PI/2 + armSwing + (phase*Math.PI/2);
                    const curAngle = Math.PI/2 + Math.sin(runProgress * Math.PI * 2 / 5 + idx*Math.PI/2);
                    const delta = targetAngle - curAngle;
                    const speed = 1.0;
                    const add = speed * (clock.getElapsedTime() - (t - Math.floor(t/5)*5));
                    const newAngle = curAngle + delta * (1 - (t - Math.floor(t)) * 5);
                    a.rotation.set(0,0,newAngle);
                });
            }
            // ---- STAND AGAIN ----
            else {
                humanoid.rotation.set(0,0,0);
                legs.forEach(l => l.rotation.set(0,0,0));
                arms.forEach(a => a.rotation.set(0,0,0));
            }
        };

        const animate = () => {
            requestAnimationFrame(animate);
            cycle();
            renderer.render(scene, camera);
        };
        animate();
    </script>
</body>
</html>
```
